```java
public static int countDoubles(String s) {
    int count = 0;
    for (int i = 0; i < s.length() - 1; i++) {
        if (s.substring(i, i + 1).equals(s.substring(i + 1, i + 2))) {
            count++;
        }
    }
    return count;
}
```

```java
public static int longestRun(String s) {
    int best = 1;
    int cur = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            cur++;
        } else {
            cur = 1;
        }
        if (cur > best) {
            best = cur;
        }
    }
    return best;
}
```

```java
public class ScoreKeeper {
    private static int totalScores = 0;
    private String name;
    private int sum;
    private int count;
    private int best;
    public ScoreKeeper(String name) {
        this.name = name;
        best = -1;
    }
    public void addScore(int s) {
        sum += s;
        count++;
        totalScores++;
        if (s > best) {
            best = s;
        }
    }
    public double getAverage() {
        if (count == 0) {
            return 0.0;
        }
        return (double) sum / count;
    }
    public int getBest() {
        return best;
    }
    public static int getTotalScores() {
        return totalScores;
    }
}
```

